    private static ProcessQueryResult Activity(ProcessSnapshot p, ProcessInsight i, List<string> evidence)
    {
        evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Tipo proposto dalle regole: {(i.Role)}. Il punteggio del classificatore è disponibile nel rapporto tecnico."));
        evidence.Add(p.CpuSampleAvailable ? global::ProcessLens.Core.SysPulseLocalization.Capture($"CPU osservata: {(p.CpuPercent):F1}%") : global::ProcessLens.Core.SysPulseLocalization.Literal("CPU: campione non disponibile"));

        var observed = new List<string>();
        if (!p.CpuSampleAvailable) observed.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("CPU non disponibile"));
        else if (p.CpuPercent >= 10) observed.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("CPU molto attiva"));
        else if (p.CpuPercent >= 2) observed.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("CPU attiva"));
        else if (p.CpuPercent >= 0.2) observed.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("attività CPU leggera"));
        else observed.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("utilizzo CPU minimo in questo intervallo"));

        if (p.IsDeepInspected)
        {
            if (p.TcpListeningCount > 0)
            {
                observed.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"{(p.TcpListeningCount)} socket TCP in ascolto"));
                evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Porte TCP LISTEN: {((p.ListeningTcpPorts.Count == 0 ? global::ProcessLens.Core.SysPulseLocalization.Literal("non esposte") : global::ProcessLens.Core.SysPulseLocalization.Join(global::ProcessLens.Core.SysPulseLocalization.Literal(", "),p.ListeningTcpPorts)))}"));
            }
            if (p.TcpEstablishedCount > 0)
            {
                observed.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"{(p.TcpEstablishedCount)} connessioni TCP stabilite"));
                evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"TCP ESTABLISHED attribuite al PID: {(p.TcpEstablishedCount)}"));
            }
            if (p.UdpEndpointCount > 0)
                observed.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"{(p.UdpEndpointCount)} endpoint UDP"));

            bool directNetwork = p.TcpListeningCount > 0 || p.TcpEstablishedCount > 0 || p.UdpEndpointCount > 0;
            bool familyNetwork = p.NetworkFamilyTcpListeningCount > 0 ||
                                 p.NetworkFamilyTcpEstablishedCount > 0 ||
                                 p.NetworkFamilyUdpEndpointCount > 0;
            if (!directNetwork && familyNetwork && p.NetworkFamilyProcessCount > 1)
            {
                observed.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("nessuna socket diretta; rete osservata in processi correlati dello stesso eseguibile"));
                evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Famiglia stesso eseguibile con socket: {(p.NetworkFamilyProcessesWithSockets)}/{(p.NetworkFamilyProcessCount)}"));
            }

            if (p.HasVisibleWindow)
                observed.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("possiede una finestra visibile"));
        }

        string body =
            global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Capture($"{(i.Summary)}. {(i.WhatIsIt)}\n\n"),global::ProcessLens.Core.SysPulseLocalization.Capture($"Adesso: {(global::ProcessLens.Core.SysPulseLocalization.Join(global::ProcessLens.Core.SysPulseLocalization.Literal("; "),observed))}."));

        return Result(global::ProcessLens.Core.SysPulseLocalization.Literal("Cosa sta facendo"), body, i.RoleConfidenceLabel, evidence);
    }

    private static ProcessQueryResult Progress(
        ProcessSnapshot p,
        ProcessInsight i,
        ProgressEvidence? progress,
        ProcessProgressSample? sample,
        List<string> evidence)
    {
        if (progress is not null)
        {
            evidence.Add(progress.Description);
            return Result(
                global::ProcessLens.Core.SysPulseLocalization.Literal("Progresso"),
                global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Capture($"Ho riconosciuto un possibile indicatore testuale di avanzamento: {(progress.Percent):F1}%. "),global::ProcessLens.Core.SysPulseLocalization.Capture($"Segnale osservato: {(progress.Description)}.\n\n")),global::ProcessLens.Core.SysPulseLocalization.Literal("È un valore letto nel titolo della finestra o nei parametri: può riferirsi a una fase, a un valore iniziale o a un obiettivo. Non verifica il completamento del lavoro.")),
                progress.ConfidenceLabel,
                evidence,
                sample);
        }

        if (LooksLongLived(i))
        {
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Ruolo long-running: {(i.Role)}"));
            return Result(
                global::ProcessLens.Core.SysPulseLocalization.Literal("Progresso"),
                global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Opaque(global::ProcessLens.Core.SysPulseLocalization.Literal("Questo processo sembra essere un componente a lunga durata (servizio, renderer, host o processo principale). ")),global::ProcessLens.Core.SysPulseLocalization.Literal("Per questo non ha necessariamente una 'percentuale completata' o una fine prevista.")),
                global::ProcessLens.Core.SysPulseLocalization.Literal("NON DETERMINATO"),
                evidence);
        }

        evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Nessun contatore di progresso esplicito trovato in command line o titoli finestra."));
        return Result(
            global::ProcessLens.Core.SysPulseLocalization.Literal("Progresso"),
            global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("ProcessLens vede che il processo è attivo, ma non dispone di un totale di lavoro affidabile. "),global::ProcessLens.Core.SysPulseLocalization.Literal("CPU, RAM o tempo trascorso da soli non permettono di dire correttamente 'a che punto è'.")),
            global::ProcessLens.Core.SysPulseLocalization.Literal("NON DETERMINATO"),
            evidence);
    }

    private static ProcessQueryResult Eta(
        ProcessSnapshot p,
        ProcessInsight i,
        ProgressEvidence? progress,
        ProcessProgressSample? current,
        ProcessProgressSample? previous,
        List<string> evidence)
    {
        if (LooksLongLived(i) && progress is null)
        {
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Ruolo long-running: {(i.Role)}"));
            return Result(
                global::ProcessLens.Core.SysPulseLocalization.Literal("Tempo alla fine"),
                global::ProcessLens.Core.SysPulseLocalization.Literal("Il tipo suggerito è compatibile con un componente a lunga durata. Non è disponibile un indicatore di progresso: la fine del processo e quella dei suoi singoli lavori non sono stimabili."),
                global::ProcessLens.Core.SysPulseLocalization.Literal("NON DETERMINATO"),
                evidence);
        }

        if (progress is null || current is null)
        {
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Nessun indicatore esplicito current/total o percentuale osservato."));
            return Result(
                global::ProcessLens.Core.SysPulseLocalization.Literal("Tempo alla fine"),
                global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Non posso stimare in modo affidabile quando finirà. Manca un indicatore di progresso osservabile: "),global::ProcessLens.Core.SysPulseLocalization.Literal("senza sapere quanto lavoro totale resta, una previsione basata solo su CPU/RAM sarebbe inventata.")),
                global::ProcessLens.Core.SysPulseLocalization.Literal("NON STIMABILE"),
                evidence);
        }

        evidence.Add(progress.Description);

        if (previous is null || !SameProgressSeries(previous, current))
        {
            return Result(
                global::ProcessLens.Core.SysPulseLocalization.Literal("Tempo alla fine"),
                global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Capture($"Il testo disponibile contiene un possibile progresso del {(progress.Percent):F1}%, ma questa è la prima osservazione utile. "),global::ProcessLens.Core.SysPulseLocalization.Literal("Per calcolare una velocità devo confrontarla con una seconda osservazione dello stesso indicatore. ")),global::ProcessLens.Core.SysPulseLocalization.Literal("Ripeti la domanda dopo un po': ProcessLens conserverà questo punto come riferimento.")),
                global::ProcessLens.Core.SysPulseLocalization.Literal("IN ATTESA DI UN SECONDO CAMPIONE"),
                evidence,
                current);
        }

        double elapsedSeconds = (current.TimestampUtc - previous.TimestampUtc).TotalSeconds;
        double delta = current.Percent - previous.Percent;
        if (elapsedSeconds <= 0 || delta <= 0.0001)
        {
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Campione precedente: {(previous.Percent):F1}%"));
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Campione attuale: {(current.Percent):F1}%"));
            return Result(
                global::ProcessLens.Core.SysPulseLocalization.Literal("Tempo alla fine"),
                global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Capture($"Il progresso osservato è {(current.Percent):F1}%, ma tra i due campioni non è avanzato abbastanza per ricavare una velocità positiva. "),global::ProcessLens.Core.SysPulseLocalization.Literal("Può essere in una fase lenta, in attesa o il contatore può aggiornarsi a intervalli più lunghi.")),
                global::ProcessLens.Core.SysPulseLocalization.Literal("NON ANCORA STIMABILE"),
                evidence,
                current);
        }

        double ratePerSecond = delta / elapsedSeconds;
        double secondsRemaining = Math.Max(0, (100.0 - current.Percent) / ratePerSecond);
        if (double.IsInfinity(secondsRemaining) || double.IsNaN(secondsRemaining) || secondsRemaining > TimeSpan.FromDays(30).TotalSeconds)
        {
            return Result(
                global::ProcessLens.Core.SysPulseLocalization.Literal("Tempo alla fine"),
                global::ProcessLens.Core.SysPulseLocalization.Literal("Il valore testuale aumenta, ma la sua variazione produce una stima troppo instabile. Servono altri campioni e una verifica del significato dell’indicatore."),
                global::ProcessLens.Core.SysPulseLocalization.Literal("BASSA"),
                evidence,
                current);
        }

        string eta = FormatDuration(TimeSpan.FromSeconds(secondsRemaining));
        string low = FormatDuration(TimeSpan.FromSeconds(secondsRemaining * 0.75));
        string high = FormatDuration(TimeSpan.FromSeconds(secondsRemaining * 1.35));
        string confidence = global::ProcessLens.Core.SysPulseLocalization.Literal("STIMA CONDIZIONATA DA DUE CAMPIONI TESTUALI");

        evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Avanzamento: {(previous.Percent):F1}% -> {(current.Percent):F1}% in {(FormatDuration(TimeSpan.FromSeconds(elapsedSeconds)))}"));
        evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Velocità osservata: {(ratePerSecond * 60):F2} punti percentuali/minuto"));

        return Result(
            global::ProcessLens.Core.SysPulseLocalization.Literal("Tempo alla fine"),
            global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Capture($"Possibile progresso testuale: {(current.Percent):F1}%. Alla velocità osservata tra gli ultimi due campioni, l'ETA è circa {(eta)}. "),global::ProcessLens.Core.SysPulseLocalization.Capture($"Scenario aritmetico (-25% / +35% della stima): {(low)} - {(high)}; non è un intervallo di confidenza.\n\n")),global::ProcessLens.Core.SysPulseLocalization.Literal("La stima assume che il testo rappresenti il lavoro completato e che la velocità resti costante; fasi e totali possono cambiare. Non è una previsione calibrata.")),
            confidence,
            evidence,
            current);
    }

    private static ProcessQueryResult Health(ProcessSnapshot p, ProcessInsight i, IReadOnlyList<double>? recentCpu, List<string> evidence)
    {
        if (!p.CpuSampleAvailable && recentCpu is not { Count: > 0 })
            return Result(global::ProcessLens.Core.SysPulseLocalization.Literal("È bloccato?"), global::ProcessLens.Core.SysPulseLocalization.Literal("Campioni CPU non disponibili. Lo stato TCP, se presente, non permette di diagnosticare o escludere un blocco."),
                global::ProcessLens.Core.SysPulseLocalization.Literal("DATI INSUFFICIENTI"), evidence);
        double avg = recentCpu is { Count: > 0 } ? recentCpu.Average() : p.CpuPercent;
        double max = recentCpu is { Count: > 0 } ? recentCpu.Max() : p.CpuPercent;
        evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"CPU media campioni recenti: {(avg):F2}%"));
        evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"CPU massima campioni recenti: {(max):F2}%"));

        if (max >= 0.5 || p.TcpEstablishedCount > 0)
        {
            if (p.TcpEstablishedCount > 0)
                evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Connessioni TCP stabilite: {(p.TcpEstablishedCount)}"));
            return Result(
                global::ProcessLens.Core.SysPulseLocalization.Literal("È bloccato?"),
                global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("CPU e stato TCP forniscono solo segnali parziali: non bastano per stabilire se il processo sia bloccato. "),global::ProcessLens.Core.SysPulseLocalization.Literal("Queste misure non permettono di escludere un blocco parziale: per verificarlo servono segnali di progresso o informazioni sui thread.")),
                global::ProcessLens.Core.SysPulseLocalization.Literal("NON DETERMINATO"),
                evidence);
        }

        return Result(
            global::ProcessLens.Core.SysPulseLocalization.Literal("È bloccato?"),
            global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Nei campioni disponibili la CPU misurata è molto bassa, ma questo NON dimostra che il processo sia bloccato: "),global::ProcessLens.Core.SysPulseLocalization.Literal("potrebbe semplicemente essere in attesa di input, rete, timer o eventi. Per diagnosticare uno stallo servirebbero anche I/O e stato dei thread.")),
            global::ProcessLens.Core.SysPulseLocalization.Literal("NON DETERMINATO"),
            evidence);
    }

    private static ProcessQueryResult Network(ProcessSnapshot p, List<string> evidence)
    {
        if (!p.IsDeepInspected)
            return Result(
                global::ProcessLens.Core.SysPulseLocalization.Literal("Porte e connessioni"),
                global::ProcessLens.Core.SysPulseLocalization.Literal("La rete di questo PID non è ancora stata ispezionata. Seleziona il processo e riprova."),
                global::ProcessLens.Core.SysPulseLocalization.Literal("NON DISPONIBILE"),
                evidence);

        evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"PID diretto - TCP LISTEN: {(p.TcpListeningCount)}"));
        evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"PID diretto - TCP ESTABLISHED: {(p.TcpEstablishedCount)}"));
        evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"PID diretto - UDP endpoint: {(p.UdpEndpointCount)}"));
        evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"PID diretto - connessioni TCP verso IP pubblici: {(p.PublicRemoteConnectionCount)}"));

        var sb = new StringBuilder();

        global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Literal("DETTAGLIO RETE DEL PROCESSO SELEZIONATO"));
        global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Literal("Conteggi di socket/endpoint, non traffico o richieste. Zero indica nessuna voce rilevata nelle letture disponibili, non un’assenza garantita."));
        if (!string.IsNullOrWhiteSpace(p.DeepInspectionNote))
            global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Esito/limiti acquisizione: "),p.DeepInspectionNote));
        if (p.TcpListeningCount > 0)
        {
            global::ProcessLens.Core.SysPulseLocalization.Append(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($"- Socket TCP LISTEN rilevate: {(p.TcpListeningCount)}"));
            if (p.ListeningTcpPorts.Count > 0)
                global::ProcessLens.Core.SysPulseLocalization.Append(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($" ({(global::ProcessLens.Core.SysPulseLocalization.Join(global::ProcessLens.Core.SysPulseLocalization.Literal(", "),p.ListeningTcpPorts))})"));
            global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb);
        }
        else
        {
            global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Literal("- Nessuna socket TCP LISTEN rilevata nelle letture disponibili; non garantisce assenza di socket."));
        }

        global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($"- Connessioni TCP stabilite: {(p.TcpEstablishedCount)}"));
        global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($"- Endpoint UDP: {(p.UdpEndpointCount)}"));
        global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($"- Connessioni TCP verso indirizzi pubblici: {(p.PublicRemoteConnectionCount)}"));

        var directEstablished = p.NetworkEndpoints
            .Where(x => x.Protocol == global::ProcessLens.Core.SysPulseLocalization.Literal("TCP") && x.State == global::ProcessLens.Core.SysPulseLocalization.Literal("ESTABLISHED"))
            .Take(6)
            .ToArray();
        if (directEstablished.Length > 0)
        {
            global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb);
            global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Literal("Connessioni osservate del PID:"));
            foreach (var ep in directEstablished)
                global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($"- {(ep.LocalAddress)}:{(ep.LocalPort)} -> {(ep.RemoteAddress)}:{(ep.RemotePort)} [{(ep.Scope)}]"));
        }

        var listeners = p.NetworkEndpoints
            .Where(x => x.Protocol == global::ProcessLens.Core.SysPulseLocalization.Literal("TCP") && x.State == global::ProcessLens.Core.SysPulseLocalization.Literal("LISTEN"))
            .Take(6)
            .ToArray();
        if (listeners.Length > 0)
        {
            global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb);
            global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Literal("Porte in ascolto del PID:"));
            foreach (var ep in listeners)
                global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($"- {(ep.LocalAddress)}:{(ep.LocalPort)} [{(ep.Scope)}]"));
        }

        if (p.NetworkFamilyProcessCount > 1)
        {
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Famiglia per nome/albero: {(p.NetworkFamilyProcessCount)} processi"));
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Famiglia - processi con socket: {(p.NetworkFamilyProcessesWithSockets)}"));
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Famiglia - TCP pubbliche: {(p.NetworkFamilyPublicRemoteConnectionCount)}"));

            global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb);
            global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Literal("PROCESSI CORRELATI PER NOME E ALBERO"));
            global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($"- Processi correlati analizzati: {(p.NetworkFamilyProcessCount)}"));
            global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($"- Processi che possiedono socket: {(p.NetworkFamilyProcessesWithSockets)}"));
            global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($"- TCP stabilite totali: {(p.NetworkFamilyTcpEstablishedCount)}"));
            global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($"- TCP in ascolto totali: {(p.NetworkFamilyTcpListeningCount)}"));
            global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($"- UDP totali: {(p.NetworkFamilyUdpEndpointCount)}"));
            global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($"- TCP verso indirizzi pubblici: {(p.NetworkFamilyPublicRemoteConnectionCount)}"));

            var networkOwners = p.RelatedNetworkProcesses
                .Where(x => x.Pid != p.Pid)
                .Take(8)
                .ToArray();

            if (networkOwners.Length > 0)
            {
                global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb);
                global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Literal("PID con socket rilevate (ruolo suggerito):"));
                foreach (var owner in networkOwners)
                {
                    global::ProcessLens.Core.SysPulseLocalization.Append(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($"- PID {(owner.Pid)}: {(owner.RoleHint)}; TCP {(owner.TcpEstablishedCount)} stabilite, "));
                    global::ProcessLens.Core.SysPulseLocalization.Append(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($"LISTEN {(owner.TcpListeningCount)}, UDP {(owner.UdpEndpointCount)}"));
                    if (owner.PublicRemoteConnectionCount > 0)
                        global::ProcessLens.Core.SysPulseLocalization.Append(sb,global::ProcessLens.Core.SysPulseLocalization.Capture($", pubbliche {(owner.PublicRemoteConnectionCount)}"));
                    global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Literal("."));
                }
            }

            var declaredNetworkService = p.RelatedNetworkProcesses
                .FirstOrDefault(x => x.RoleHint.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("Servizio di rete"), StringComparison.OrdinalIgnoreCase));

            if (p.TcpEstablishedCount == 0 && p.UdpEndpointCount == 0 && declaredNetworkService is not null)
            {
                global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb);
                global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Capture($"Interpretazione: nelle letture disponibili non risultano connessioni TCP ESTABLISHED o endpoint UDP per il PID selezionato. "),global::ProcessLens.Core.SysPulseLocalization.Capture($"La famiglia contiene invece il PID {(declaredNetworkService.Pid)}, identificato dalla command line come servizio di rete, ")),global::ProcessLens.Core.SysPulseLocalization.Literal("con socket rilevate. La correlazione fra processi non dimostra che questo PID gli abbia delegato le operazioni di rete.")));
            }
            else if (p.TcpEstablishedCount == 0 && p.UdpEndpointCount == 0 && p.NetworkFamilyProcessesWithSockets > 0)
            {
                global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb);
                global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb,global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Interpretazione: non risultano connessioni TCP ESTABLISHED o endpoint UDP per questo PID; altri processi correlati hanno socket rilevate. Eventuali socket LISTEN sono riportate separatamente. "),global::ProcessLens.Core.SysPulseLocalization.Literal("ProcessLens può quindi dire dove sono le socket, senza attribuirle erroneamente al PID selezionato.")));
            }
        }

        global::ProcessLens.Core.SysPulseLocalization.AppendLine(sb);
        if (p.PublicRemoteConnectionCount > 0)
        {
            global::ProcessLens.Core.SysPulseLocalization.Append(sb,global::ProcessLens.Core.SysPulseLocalization.Literal("Conclusione: Windows riporta per questo PID connessioni TCP verso indirizzi classificati pubblici; i byte trasferiti non sono misurati. "));
        }
        else if (p.NetworkFamilyPublicRemoteConnectionCount > 0)
        {
            global::ProcessLens.Core.SysPulseLocalization.Append(sb,global::ProcessLens.Core.SysPulseLocalization.Literal("Conclusione: non sono rilevate connessioni TCP pubbliche sul PID selezionato; sono rilevate su processi correlati. "));
        }
        else
        {
            global::ProcessLens.Core.SysPulseLocalization.Append(sb,global::ProcessLens.Core.SysPulseLocalization.Literal("Conclusione: nello snapshot attuale non sono state osservate connessioni TCP verso indirizzi pubblici. "));
        }

        global::ProcessLens.Core.SysPulseLocalization.Append(sb,global::ProcessLens.Core.SysPulseLocalization.Literal("La classificazione dell’indirizzo come pubblico non prova il percorso di rete, la raggiungibilità, un trasferimento o il servizio remoto utilizzato. "));
        global::ProcessLens.Core.SysPulseLocalization.Append(sb,global::ProcessLens.Core.SysPulseLocalization.Literal("Una porta LISTEN su 127.0.0.1/::1 è solo locale; 0.0.0.0/:: indica tutte le interfacce locali, ma firewall/NAT determinano l'effettiva raggiungibilità dall'esterno."));

        return Result(global::ProcessLens.Core.SysPulseLocalization.Literal("Porte e connessioni"), global::ProcessLens.Core.SysPulseLocalization.Map(global::ProcessLens.Core.SysPulseLocalization.BuilderText(sb),__s=>__s.Trim()), global::ProcessLens.Core.SysPulseLocalization.Literal("OSSERVATO"), evidence);
    }

    private static ProcessQueryResult Origin(ProcessSnapshot p, ProcessInsight i, List<string> evidence)
    {
        var origin = ProcessOriginAnalyzer.Analyze(p);
        evidence.AddRange(origin.Evidence);
        return Result(global::ProcessLens.Core.SysPulseLocalization.Literal("Origine e operazione"),
            global::ProcessLens.Core.SysPulseLocalization.Capture($"{(origin.ParentSummary)}\n\n{(origin.Operation)}\n\nCATENA DI AVVIO\n{(origin.Chain)}\n\n{(origin.Limitations)}"),
            p.AncestorDetails.Count > 0 && p.AncestorDetails.All(a => a.VerifiedByStartTime)
                ? global::ProcessLens.Core.SysPulseLocalization.Literal("CATENA COMPATIBILE PER ORARI") : global::ProcessLens.Core.SysPulseLocalization.Literal("CATENA PARZIALE"),
            evidence);
    }

    private static ProcessQueryResult WhyRunning(ProcessSnapshot p, ProcessInsight i, List<string> evidence)
    {
        var origin = ProcessOriginAnalyzer.Analyze(p);
        evidence.AddRange(origin.Evidence);
        evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Ruolo: {(i.Role)}"));
        if (p.ParentName is not null) evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Processo padre: {(p.ParentName)}"));
        return Result(global::ProcessLens.Core.SysPulseLocalization.Literal("Perché è aperto"),
            global::ProcessLens.Core.SysPulseLocalization.Capture($"{(i.WhyRunning)}\n\nORIGINE: {(origin.ParentSummary)}\nOPERAZIONE: {(origin.Operation)}\n\n{(origin.Limitations)}"),
            global::ProcessLens.Core.SysPulseLocalization.Literal("DATI DI AVVIO + TIPO SUGGERITO"), evidence);
    }

    private static ProcessQueryResult Termination(ProcessSnapshot p, ProcessInsight i, List<string> evidence)
    {
        if (p.IsCritical) evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Windows marca il processo come critico."));
        evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Valutazione rischio: {(i.CloseRisk)}"));
        return Result(
            global::ProcessLens.Core.SysPulseLocalization.Literal("Se lo chiudo"),
            global::ProcessLens.Core.SysPulseLocalization.Capture($"{(i.CloseImpact)}\n\nPossibili conseguenze secondo le regole (non verificate nel processo in corso). Rischio orientativo: {(i.CloseRisk)}."),
            p.IsCritical ? global::ProcessLens.Core.SysPulseLocalization.Literal("CRITICO") : global::ProcessLens.Core.SysPulseLocalization.Literal("EFFETTI STIMATI; STATO NON VERIFICATO"),
            evidence);
    }

