    private static IReadOnlyList<ProcessQueryIntent> DetectIntents(string question)
    {
        string q = global::ProcessLens.Core.SysPulseLocalization.Map(question,__s=>__s.ToLowerInvariant());
        var intents = new List<ProcessQueryIntent>();

        if (ContainsAny(q, global::ProcessLens.Core.SysPulseLocalization.Literal("cosa sta facendo"), global::ProcessLens.Core.SysPulseLocalization.Literal("cosa fa"), global::ProcessLens.Core.SysPulseLocalization.Literal("che fa"), global::ProcessLens.Core.SysPulseLocalization.Literal("attività"), global::ProcessLens.Core.SysPulseLocalization.Literal("attivita"), global::ProcessLens.Core.SysPulseLocalization.Literal("sta facendo"), global::ProcessLens.Core.SysPulseLocalization.Literal("what is it doing"), global::ProcessLens.Core.SysPulseLocalization.Literal("what does it do"))) intents.Add(ProcessQueryIntent.Activity);
        bool cpuQuestion = ContainsAny(q, global::ProcessLens.Core.SysPulseLocalization.Literal("cpu"), global::ProcessLens.Core.SysPulseLocalization.Literal("processore"), global::ProcessLens.Core.SysPulseLocalization.Literal("core"), global::ProcessLens.Core.SysPulseLocalization.Literal("carico del computer"), global::ProcessLens.Core.SysPulseLocalization.Literal("processor"));
        if (cpuQuestion) intents.Add(ProcessQueryIntent.Cpu);
        if (Regex.IsMatch(q, global::ProcessLens.Core.SysPulseLocalization.Literal(@"\bram\b|\b\d+\s*(?:mb|gb)\b")) || ContainsAny(q, global::ProcessLens.Core.SysPulseLocalization.Literal("memoria"), global::ProcessLens.Core.SysPulseLocalization.Literal("working set"), global::ProcessLens.Core.SysPulseLocalization.Literal("commit"), global::ProcessLens.Core.SysPulseLocalization.Literal("megabyte"), global::ProcessLens.Core.SysPulseLocalization.Literal("gigabyte"), global::ProcessLens.Core.SysPulseLocalization.Literal("memory"), global::ProcessLens.Core.SysPulseLocalization.Literal("cache"), global::ProcessLens.Core.SysPulseLocalization.Literal("perdita di memoria"), global::ProcessLens.Core.SysPulseLocalization.Literal("memory leak")))
            intents.Add(ProcessQueryIntent.Memory);
        if (ContainsAny(q, global::ProcessLens.Core.SysPulseLocalization.Literal("a che punto"), global::ProcessLens.Core.SysPulseLocalization.Literal("progresso"), global::ProcessLens.Core.SysPulseLocalization.Literal("avanzamento"), global::ProcessLens.Core.SysPulseLocalization.Literal("quanto ha fatto"), global::ProcessLens.Core.SysPulseLocalization.Literal("progress"), global::ProcessLens.Core.SysPulseLocalization.Literal("how far")) ||
            (!cpuQuestion && ContainsAny(q, global::ProcessLens.Core.SysPulseLocalization.Literal("percentuale"), global::ProcessLens.Core.SysPulseLocalization.Literal("percent")))) intents.Add(ProcessQueryIntent.Progress);
        if (ContainsAny(q, global::ProcessLens.Core.SysPulseLocalization.Literal("quanto manca"), global::ProcessLens.Core.SysPulseLocalization.Literal("quando finir"), global::ProcessLens.Core.SysPulseLocalization.Literal("quando finisc"), global::ProcessLens.Core.SysPulseLocalization.Literal("tempo alla fine"), global::ProcessLens.Core.SysPulseLocalization.Literal("eta"), global::ProcessLens.Core.SysPulseLocalization.Literal("tra quanto"), global::ProcessLens.Core.SysPulseLocalization.Literal("when will it finish"), global::ProcessLens.Core.SysPulseLocalization.Literal("time remaining"))) intents.Add(ProcessQueryIntent.Eta);
        if (ContainsAny(q, global::ProcessLens.Core.SysPulseLocalization.Literal("bloccato"), global::ProcessLens.Core.SysPulseLocalization.Literal("bloccata"), global::ProcessLens.Core.SysPulseLocalization.Literal("fermo"), global::ProcessLens.Core.SysPulseLocalization.Literal("ferma"), global::ProcessLens.Core.SysPulseLocalization.Literal("stall"), global::ProcessLens.Core.SysPulseLocalization.Literal("risponde"), global::ProcessLens.Core.SysPulseLocalization.Literal("stuck"), global::ProcessLens.Core.SysPulseLocalization.Literal("frozen"), global::ProcessLens.Core.SysPulseLocalization.Literal("hanging"))) intents.Add(ProcessQueryIntent.Health);
        if (ContainsAny(q, global::ProcessLens.Core.SysPulseLocalization.Literal("internet"), global::ProcessLens.Core.SysPulseLocalization.Literal("rete"), global::ProcessLens.Core.SysPulseLocalization.Literal("connession"), global::ProcessLens.Core.SysPulseLocalization.Literal("socket"), global::ProcessLens.Core.SysPulseLocalization.Literal("network"), global::ProcessLens.Core.SysPulseLocalization.Literal("connection")) || Regex.IsMatch(q, global::ProcessLens.Core.SysPulseLocalization.Literal(@"\b(?:porta|porte|port|ports)\b"))) intents.Add(ProcessQueryIntent.Network);
        if (ContainsAny(q, global::ProcessLens.Core.SysPulseLocalization.Literal("chi lo ha avviato"), global::ProcessLens.Core.SysPulseLocalization.Literal("chi l'ha avviato"), global::ProcessLens.Core.SysPulseLocalization.Literal("chi ha avviato"), global::ProcessLens.Core.SysPulseLocalization.Literal("origine"), global::ProcessLens.Core.SysPulseLocalization.Literal("processo padre"), global::ProcessLens.Core.SysPulseLocalization.Literal("parent"), global::ProcessLens.Core.SysPulseLocalization.Literal("da chi"), global::ProcessLens.Core.SysPulseLocalization.Literal("da dove"), global::ProcessLens.Core.SysPulseLocalization.Literal("dove è partito"), global::ProcessLens.Core.SysPulseLocalization.Literal("dove e partito"), global::ProcessLens.Core.SysPulseLocalization.Literal("chi l'ha lanciato"), global::ProcessLens.Core.SysPulseLocalization.Literal("chi lo ha lanciato"), global::ProcessLens.Core.SysPulseLocalization.Literal("perché è partito"), global::ProcessLens.Core.SysPulseLocalization.Literal("perche e partito"), global::ProcessLens.Core.SysPulseLocalization.Literal("cosa lo ha avviato"), global::ProcessLens.Core.SysPulseLocalization.Literal("who started"), global::ProcessLens.Core.SysPulseLocalization.Literal("origin"))) intents.Add(ProcessQueryIntent.Origin);
        if (ContainsAny(q, global::ProcessLens.Core.SysPulseLocalization.Literal("perché è aperto"), global::ProcessLens.Core.SysPulseLocalization.Literal("perche e aperto"), global::ProcessLens.Core.SysPulseLocalization.Literal("perché è attivo"), global::ProcessLens.Core.SysPulseLocalization.Literal("perche e attivo"), global::ProcessLens.Core.SysPulseLocalization.Literal("perché gira"), global::ProcessLens.Core.SysPulseLocalization.Literal("perche gira"), global::ProcessLens.Core.SysPulseLocalization.Literal("why is it running"), global::ProcessLens.Core.SysPulseLocalization.Literal("why is it open"))) intents.Add(ProcessQueryIntent.WhyRunning);
        if (ContainsAny(q, global::ProcessLens.Core.SysPulseLocalization.Literal("posso chiuder"), global::ProcessLens.Core.SysPulseLocalization.Literal("se lo chiudo"), global::ProcessLens.Core.SysPulseLocalization.Literal("termin"), global::ProcessLens.Core.SysPulseLocalization.Literal("kill"), global::ProcessLens.Core.SysPulseLocalization.Literal("sicuro chiud"), global::ProcessLens.Core.SysPulseLocalization.Literal("can i close"), global::ProcessLens.Core.SysPulseLocalization.Literal("safe to close"))) intents.Add(ProcessQueryIntent.Termination);

        return intents.Distinct().ToArray();
    }

    private static bool ContainsAny(string value, params string[] terms) => terms.Any(term => value.Contains(term, StringComparison.Ordinal));

    private static bool SameProgressSeries(ProcessProgressSample a, ProcessProgressSample b)
    {
        if (a.Pid != b.Pid) return false;
        if (a.StartTime.HasValue && b.StartTime.HasValue && a.StartTime.Value != b.StartTime.Value) return false;
        return string.Equals(a.SourceKey, b.SourceKey, StringComparison.OrdinalIgnoreCase);
    }

    private static bool LooksLongLived(ProcessInsight insight)
    {
        string s = global::ProcessLens.Core.SysPulseLocalization.Map(global::ProcessLens.Core.SysPulseLocalization.Capture($"{(insight.Role)} {(insight.Summary)}"),__s=>__s.ToLowerInvariant());
        string[] signals =
        {
            global::ProcessLens.Core.SysPulseLocalization.Literal("renderer"), global::ProcessLens.Core.SysPulseLocalization.Literal("gpu"), global::ProcessLens.Core.SysPulseLocalization.Literal("servizio"), global::ProcessLens.Core.SysPulseLocalization.Literal("service"), global::ProcessLens.Core.SysPulseLocalization.Literal("server"), global::ProcessLens.Core.SysPulseLocalization.Literal("host"), global::ProcessLens.Core.SysPulseLocalization.Literal("processo principale"),
            global::ProcessLens.Core.SysPulseLocalization.Literal("coordinatore"), global::ProcessLens.Core.SysPulseLocalization.Literal("language server"), global::ProcessLens.Core.SysPulseLocalization.Literal("utility"), global::ProcessLens.Core.SysPulseLocalization.Literal("shell"), global::ProcessLens.Core.SysPulseLocalization.Literal("runtime"), global::ProcessLens.Core.SysPulseLocalization.Literal("crash"), global::ProcessLens.Core.SysPulseLocalization.Literal("rete"), global::ProcessLens.Core.SysPulseLocalization.Literal("audio")
        };
        return signals.Any(signal => s.Contains(signal, StringComparison.Ordinal));
