    private static string FormatDuration(TimeSpan value)
    {
        if (value.TotalSeconds < 1) return global::ProcessLens.Core.SysPulseLocalization.Literal("meno di 1 secondo");
        if (value.TotalMinutes < 1) return global::ProcessLens.Core.SysPulseLocalization.Capture($"{(Math.Round(value.TotalSeconds)):0} s");
        if (value.TotalHours < 1) return global::ProcessLens.Core.SysPulseLocalization.Capture($"{((int)value.TotalMinutes)} min {(value.Seconds)} s");
        if (value.TotalDays < 1) return global::ProcessLens.Core.SysPulseLocalization.Capture($"{((int)value.TotalHours)} h {(value.Minutes)} min");
        return global::ProcessLens.Core.SysPulseLocalization.Capture($"{((int)value.TotalDays)} g {(value.Hours)} h");
    }

