    private sealed record ProgressEvidence(double Percent, string SourceKey, string Description, string ConfidenceLabel);

    private static class ProgressDetector
    {
        private static readonly string[] ProgressWords =
        {
            global::ProcessLens.Core.SysPulseLocalization.Literal("progress"), global::ProcessLens.Core.SysPulseLocalization.Literal("progresso"), global::ProcessLens.Core.SysPulseLocalization.Literal("epoch"), global::ProcessLens.Core.SysPulseLocalization.Literal("epoca"), global::ProcessLens.Core.SysPulseLocalization.Literal("step"), global::ProcessLens.Core.SysPulseLocalization.Literal("passo"), global::ProcessLens.Core.SysPulseLocalization.Literal("batch"), global::ProcessLens.Core.SysPulseLocalization.Literal("file"), global::ProcessLens.Core.SysPulseLocalization.Literal("files"),
            global::ProcessLens.Core.SysPulseLocalization.Literal("item"), global::ProcessLens.Core.SysPulseLocalization.Literal("test"), global::ProcessLens.Core.SysPulseLocalization.Literal("chunk"), global::ProcessLens.Core.SysPulseLocalization.Literal("fase"), global::ProcessLens.Core.SysPulseLocalization.Literal("phase"), global::ProcessLens.Core.SysPulseLocalization.Literal("task"), global::ProcessLens.Core.SysPulseLocalization.Literal("unit"), global::ProcessLens.Core.SysPulseLocalization.Literal("unità"), global::ProcessLens.Core.SysPulseLocalization.Literal("completed"), global::ProcessLens.Core.SysPulseLocalization.Literal("complet"),
            global::ProcessLens.Core.SysPulseLocalization.Literal("download"), global::ProcessLens.Core.SysPulseLocalization.Literal("scaric"), global::ProcessLens.Core.SysPulseLocalization.Literal("upload"), global::ProcessLens.Core.SysPulseLocalization.Literal("caric"), global::ProcessLens.Core.SysPulseLocalization.Literal("copy"), global::ProcessLens.Core.SysPulseLocalization.Literal("copi"), global::ProcessLens.Core.SysPulseLocalization.Literal("install"), global::ProcessLens.Core.SysPulseLocalization.Literal("extract"), global::ProcessLens.Core.SysPulseLocalization.Literal("estrai"),
            global::ProcessLens.Core.SysPulseLocalization.Literal("compress"), global::ProcessLens.Core.SysPulseLocalization.Literal("decompress"), global::ProcessLens.Core.SysPulseLocalization.Literal("build"), global::ProcessLens.Core.SysPulseLocalization.Literal("compil"), global::ProcessLens.Core.SysPulseLocalization.Literal("train"), global::ProcessLens.Core.SysPulseLocalization.Literal("training"), global::ProcessLens.Core.SysPulseLocalization.Literal("render"), global::ProcessLens.Core.SysPulseLocalization.Literal("encode"), global::ProcessLens.Core.SysPulseLocalization.Literal("transf")
        };

        public static ProgressEvidence? TryDetect(ProcessSnapshot p)
        {
            foreach (string title in p.WindowTitles)
            {
                var hit = TryText(title, global::ProcessLens.Core.SysPulseLocalization.Literal("window-title"), allowBarePercent: false);
                if (hit is not null) return hit with { Description = global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Titolo finestra: "),hit.Description), ConfidenceLabel = global::ProcessLens.Core.SysPulseLocalization.Literal("INDICATORE TESTUALE DA VERIFICARE") };
            }

            if (!string.IsNullOrWhiteSpace(p.CommandLine))
            {
                var hit = TryText(p.CommandLine!, global::ProcessLens.Core.SysPulseLocalization.Literal("command-line"), allowBarePercent: false);
                if (hit is not null) return hit with { Description = global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Parametri di avvio: "),hit.Description), ConfidenceLabel = global::ProcessLens.Core.SysPulseLocalization.Literal("INDICATORE TESTUALE DA VERIFICARE") };
            }

            return null;
        }

        private static ProgressEvidence? TryText(string text, string sourceKey, bool allowBarePercent)
        {
            string normalized = text.Replace(',', '.');

            var labeled = Regex.Match(
                normalized,
                global::ProcessLens.Core.SysPulseLocalization.Literal(@"(?i)\b(epoch|epoca|step|passo|batch|file(?:s)?|item|test|chunk|fase|phase|task|unit(?:à)?)\s*[:#-]?\s*(\d+(?:\.\d+)?)\s*(?:/|\bof\b|\bdi\b)\s*(\d+(?:\.\d+)?)"));
            if (labeled.Success && TryNumbers(labeled.Groups[2].Value, labeled.Groups[3].Value, out double current, out double total))
            {
                double percent = current / total * 100.0;
                string unit = labeled.Groups[1].Value;
                return new ProgressEvidence(percent, global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(sourceKey,global::ProcessLens.Core.SysPulseLocalization.Literal(":")),global::ProcessLens.Core.SysPulseLocalization.Map(unit,__s=>__s.ToLowerInvariant())), global::ProcessLens.Core.SysPulseLocalization.Capture($"{(unit)}: {(current):0.##} / {(total):0.##} ({(percent):F1}%)"), global::ProcessLens.Core.SysPulseLocalization.Literal("ALTA"));
            }

            var ofPattern = Regex.Match(normalized, global::ProcessLens.Core.SysPulseLocalization.Literal(@"(?i)\b(\d+(?:\.\d+)?)\s*(?:/|\bof\b|\bdi\b)\s*(\d+(?:\.\d+)?)\s*(file(?:s)?|item|test|chunk|task|unit(?:à)?)\b"));
            if (ofPattern.Success && TryNumbers(ofPattern.Groups[1].Value, ofPattern.Groups[2].Value, out current, out total))
            {
                double percent = current / total * 100.0;
                string unit = ofPattern.Groups[3].Value;
                return new ProgressEvidence(percent, global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(sourceKey,global::ProcessLens.Core.SysPulseLocalization.Literal(":")),global::ProcessLens.Core.SysPulseLocalization.Map(unit,__s=>__s.ToLowerInvariant())), global::ProcessLens.Core.SysPulseLocalization.Capture($"{(current):0.##} / {(total):0.##} {(unit)} ({(percent):F1}%)"), global::ProcessLens.Core.SysPulseLocalization.Literal("ALTA"));
            }

            bool hasContext = ProgressWords.Any(w => normalized.Contains(w, StringComparison.OrdinalIgnoreCase));
            if (allowBarePercent || hasContext)
            {
                var pct = Regex.Match(normalized, global::ProcessLens.Core.SysPulseLocalization.Literal(@"(?<!\d)(100(?:\.0+)?|\d{1,2}(?:\.\d+)?)\s*%"));
                if (pct.Success && double.TryParse(pct.Groups[1].Value, NumberStyles.Float, CultureInfo.InvariantCulture, out double percent) && percent is >= 0 and <= 100)
                    return new ProgressEvidence(percent, global::ProcessLens.Core.SysPulseLocalization.Concat(sourceKey,global::ProcessLens.Core.SysPulseLocalization.Literal(":percent")), global::ProcessLens.Core.SysPulseLocalization.Capture($"Percentuale esposta: {(percent):F1}%"), allowBarePercent ? global::ProcessLens.Core.SysPulseLocalization.Literal("MEDIA") : global::ProcessLens.Core.SysPulseLocalization.Literal("ALTA"));
            }

            return null;
        }

        private static bool TryNumbers(string a, string b, out double current, out double total)
        {
            current = total = 0;
            if (!double.TryParse(a, NumberStyles.Float, CultureInfo.InvariantCulture, out current)) return false;
            if (!double.TryParse(b, NumberStyles.Float, CultureInfo.InvariantCulture, out total)) return false;
            return total > 0 && current >= 0 && current <= total;
        }
    }
}

public sealed record ProcessQueryResult
{
    private string _title, _answer, _confidence;
    private IReadOnlyList<string> _evidence;
    public string Title { get => SysPulseLocalization.Render(_title); init => _title=value; }
    public string Answer { get => SysPulseLocalization.Render(_answer); init => _answer=value; }
    public string Confidence { get => SysPulseLocalization.Render(_confidence); init => _confidence=value; }
    public IReadOnlyList<string> Evidence { get => SysPulseLocalization.IsEnglish ? _evidence.Select(s=>SysPulseLocalization.Render(s)).ToArray() : _evidence; init=>_evidence=value; }
    public ProcessProgressSample? ProgressSample { get; init; }
    public ProcessQueryResult(string Title,string Answer,string Confidence,IReadOnlyList<string> Evidence,ProcessProgressSample? ProgressSample)
    { _title=Title;_answer=Answer;_confidence=Confidence;_evidence=Evidence;this.ProgressSample=ProgressSample; }
    public void Deconstruct(out string Title,out string Answer,out string Confidence,out IReadOnlyList<string> Evidence,out ProcessProgressSample? ProgressSample)
    { Title=this.Title;Answer=this.Answer;Confidence=this.Confidence;Evidence=this.Evidence;ProgressSample=this.ProgressSample; }
}

public sealed record ProcessProgressSample(
    int Pid,
    DateTime? StartTime,
